{
  "narratives": [
    {
      "item_code": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해 필요한 조치사항 및 보호구",
      "start": "p4:L5",
      "end": "p4:L14"
    },
    {
      "item_code": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해 필요한 조치사항",
      "start": "p4:L15",
      "end": "p4:L16"
    },
    {
      "item_code": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거 방법",
      "start": "p4:L17",
      "end": "p4:L23"
    }
  ],
  "extras": [
    {
      "after_item": "S6_END",
      "title_raw": "가. 인체를 보호하기 위해 필요한 조치사항 및 보호구",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "매우 미세한 입자는 화재나 폭발을 일으킬 수 있으므로 모든 점화원을 제거하시오.",
          "line": "p4:L5"
        },
        {
          "key": "내용",
          "value": "엎질러진 것을 즉시 닦아내고, 보호구 항의 예방조치를 따르시오.",
          "line": "p4:L5"
        },
        {
          "key": "내용",
          "value": "방화복·방염복을 입으시오.",
          "line": "p4:L6"
        },
        {
          "key": "내용",
          "value": "증기 및 미스트를 흡입을 피하시오.",
          "line": "p4:L7"
        },
        {
          "key": "내용",
          "value": "피해야할 물질 및 조건에 유의하시오.",
          "line": "p4:L8"
        },
        {
          "key": "내용",
          "value": "물분무를 이용하여 증기를 줄이거나 증기구름을 흩어트리시오.",
          "line": "p4:L9"
        },
        {
          "key": "내용",
          "value": "전문가의 감독 없이 청소 및 처리를 하지 마시오.",
          "line": "p4:L10"
        },
        {
          "key": "내용",
          "value": "적절한 보호의를 착용하지 않고 파손된 용기나 누출물에 손대지 마시오.",
          "line": "p4:L11"
        },
        {
          "key": "내용",
          "value": "가연성 물질과 누출물을 멀리하시오.",
          "line": "p4:L12"
        },
        {
          "key": "내용",
          "value": "오염 지역을 격리하시오.",
          "line": "p4:L13"
        },
        {
          "key": "내용",
          "value": "들어갈 필요가 없거나 보호장비를 갖추지 않은 사람은 출입하지 마시오.",
          "line": "p4:L14"
        }
      ],
      "line": "p4:L5"
    },
    {
      "after_item": "S6_PERSONAL",
      "title_raw": "나. 환경을 보호하기 위해 필요한 조치사항",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "수로, 하수구, 지하실, 밀폐공간으로의 유입을 방지하시오.",
          "line": "p4:L15"
        },
        {
          "key": "내용",
          "value": "누출물은 오염을 유발할 수 있음.",
          "line": "p4:L16"
        }
      ],
      "line": "p4:L15"
    },
    {
      "after_item": "S6_ENV",
      "title_raw": "다. 정화 또는 제거 방법",
      "reason": "코드없음",
      "statements": [
        {
          "key": "내용",
          "value": "공기성 먼지를 제거하고 물로 습윤화하여 흩어지는 것을 막으시오.",
          "line": "p4:L17"
        },
        {
          "key": "내용",
          "value": "불활성 물질(예를 들어 건조한 모래 또는 흙)로 엎지른 것을 흡수하고, 화학폐기물 용기에 넣으시오.",
          "line": "p4:L18"
        },
        {
          "key": "내용",
          "value": "소화를 위해 제방을 쌓고 물을 수거하시오.",
          "line": "p4:L20"
        },
        {
          "key": "내용",
          "value": "톱밥과 같은 가연성 물질을 사용하지 마시오.",
          "line": "p4:L21"
        },
        {
          "key": "내용",
          "value": "액체를 흡수하고 오염된 지역을 세제와 물로 씻어 내시오.",
          "line": "p4:L22"
        },
        {
          "key": "내용",
          "value": "소량 누출 시 다량의 물로 오염지역을 씻어내시오.",
          "line": "p4:L23"
        }
      ],
      "line": "p4:L17"
    }
  ]
}

